    @0x018d  HhAddChild(HhBuildStaticTextAuto(IntConst(100), IntConst(63), StrConst("Převratný vynález. Bratři Čmelíkové, specialisté na genetiku a rozmnožování,\nsestrojují první plně automatizovanou dračku peří."), IntConst(1), 65711))
