    @0x0477  HhAddChild(HhSetStaticTextStyle(HhBuildStaticTextAuto(IntConst(30), IntConst(170), StrConst("23. 2. 1995"), IntConst(1), 65711), count=2, [IntConst(0), IntConst(16777215)]))
    @0x04b1  HhAddChild(HhBuildStaticTextAuto(IntConst(100), IntConst(170), StrConst("Archeologický nález. Poblíž slovenské obce\nVankúšov jsou nalezeny ostatky Bulánčího\nlovce z doby bronzové. Tento nečekaný objev\npodává nezvratný a zároveň zneklidňující důkaz,\nže bulánčí kultura má mnohem hlubší kořeny,\nnež se vědci domnívali."), IntConst(1), 65711))
