    @0x071b  HhAddChild(HhBuildStaticTextAuto(IntConst(276), IntConst(276), StrConst("Výročí vzpoury. U příležitosti 20. výročí\nBulánčí vzpoury je uspořádána malá slavnostní\nvzpoura, která přerůstá v ničivý pochod ulicemi.\nIncident musí nakonec řešit pořádková policie."), IntConst(1), 65711))
